<template>
  <F7Page
    name="stock-search"
    @page:beforein="hideTabbar"
    @page:beforeout="showTabbar"
  >
    <F7Navbar>
      <F7Searchbar
        custom-search
        placeholder="Search products, SKUs..."
        :value="searchTerm"
        @searchbar:search="handleSearch"
        @searchbar:clear="clearSearch"
        @searchbar:disable="goBack"
      />
    </F7Navbar>

    <div class="px-[18px] pb-[100px] pt-2 max-[430px]:px-3.5">
      <div v-if="products.length" class="flex flex-col gap-2">
        <StockNeedCard
          v-for="item in products"
          :key="item.ruid"
          :name="item.name"
          :sku-label="item.sku ? `SKU ${item.sku}` : '—'"
          :state-label="productStateLabel(item.onHand)"
          :health="item.health"
          :image-src="productImageSrc(item.image)"
          @open="openProduct(item.ruid)"
        />
      </div>
      <p v-else-if="searchTerm" class="mt-10 text-center text-sm font-[540] text-[#657096]">
        No products found for "{{ searchTerm }}"
      </p>
      <p v-else class="mt-10 text-center text-sm font-[540] text-[#657096]">
        Start typing to search products
      </p>
    </div>

    <StockProductSheet v-model:opened="sheetOpen" :product-ruid="selectedRuid" />
  </F7Page>
</template>

<script setup lang="ts">
import { f7 } from "framework7-vue";
import StockNeedCard from "../components/StockNeedCard.vue";
import StockProductSheet from "../components/StockProductSheet.vue";
import { useStockDashboard } from "../composables/useStockDashboard";
import { formatCompact } from "../stock.format";
import { productImageSrc } from "../stock.visuals";

const { products, searchTerm } = useStockDashboard();

const sheetOpen = ref(false);
const selectedRuid = ref<string | null>(null);

function hideTabbar() {
  f7.toolbar.hide(".toolbar-main-app", false);
}

function showTabbar() {
  f7.toolbar.show(".toolbar-main-app", true);
}

function goBack() {
  f7.views.current.router.back();
}

function handleSearch(...args: unknown[]) {
  searchTerm.value = String(args[1] ?? "");
}

function clearSearch() {
  searchTerm.value = "";
}

function productStateLabel(onHand: number) {
  if (onHand <= 0) return "Out of stock";
  return `${formatCompact(onHand)} units`;
}

function openProduct(ruid: string) {
  selectedRuid.value = ruid;
  sheetOpen.value = true;
}
</script>
