import { sql } from "kysely";
import { rdb } from "@/shared/database";
import { useReactiveQuery } from "@/shared/composables/useReactiveQuery";
import { healthFor } from "../stock.format";
import type {
  StockOverview,
  StockCategoryStatus,
  StockNeedsActionItem,
} from "../stock.types";

interface DashboardData {
  overview: StockOverview;
  categories: StockCategoryStatus[];
  allProducts: StockNeedsActionItem[];
}

export function useStockDashboard() {
  const searchTerm = ref("");

  const { data, loading } = useReactiveQuery<DashboardData>(
    async () => {
      const products = await rdb
        .selectFrom("product_product as p")
        .leftJoin("product_template as t", "t._ruid", "p.product_tmpl_id")
        .leftJoin("product_category as c", "c._ruid", "t.categ_id")
        .select([
          "p._ruid as ruid",
          "p.name as name",
          "p.default_code as sku",
          "p.image_512 as image",
          "p.standard_price as price",
          "p.active as active",
          "c._ruid as categRuid",
          "c.name as categName",
        ])
        .where("p._delete_date", "is", null)
        .execute();

      const quants = await rdb
        .selectFrom("stock_quant")
        .select([
          "product_id",
          sql<number>`coalesce(sum(quantity),0)`.as("on_hand"),
        ])
        .where("_delete_date", "is", null)
        .groupBy("product_id")
        .execute();

      const onHandByRuid = new Map<string, number>();
      for (const q of quants) onHandByRuid.set(String(q.product_id), Number(q.on_hand ?? 0));

      let totalSkus = 0;
      let lowStock = 0;
      let outOfStock = 0;
      let stockValue = 0;
      const allProducts: StockNeedsActionItem[] = [];
      const catMap = new Map<
        string,
        { name: string; sku: number; units: number; out: number; low: number }
      >();

      for (const p of products) {
        if (Number(p.active ?? 1) === 0) continue;
        const ruid = String(p.ruid);
        const onHand = onHandByRuid.get(ruid) ?? 0;
        const health = healthFor(onHand);

        totalSkus += 1;
        stockValue += onHand * Number(p.price ?? 0);
        if (health === "critical") outOfStock += 1;
        else if (health === "low") lowStock += 1;

        allProducts.push({ ruid, name: p.name, sku: p.sku ?? null, image: p.image ?? null, onHand, health });

        const key = p.categRuid ? String(p.categRuid) : "uncategorized";
        const entry = catMap.get(key) ?? {
          name: p.categName ?? "Uncategorized",
          sku: 0,
          units: 0,
          out: 0,
          low: 0,
        };
        entry.sku += 1;
        entry.units += onHand;
        if (health === "critical") entry.out += 1;
        else if (health === "low") entry.low += 1;
        catMap.set(key, entry);
      }

      allProducts.sort((a, b) => a.onHand - b.onHand);

      const categories: StockCategoryStatus[] = [...catMap.entries()]
        .map(([ruid, e]) => ({
          ruid,
          name: e.name,
          skuCount: e.sku,
          units: e.units,
          health:
            e.out > 0 ? ("critical" as const) : e.low > 0 ? ("low" as const) : ("healthy" as const),
        }))
        .sort((a, b) => b.skuCount - a.skuCount);

      return {
        overview: { totalSkus, lowStock, outOfStock, stockValue },
        categories,
        allProducts,
      };
    },
    {
      tables: ["stock_quant", "product_product", "product_template", "product_category"],
      queryKey: "stock:dashboard",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  const overview = computed<StockOverview>(
    () => data.value?.overview ?? { totalSkus: 0, lowStock: 0, outOfStock: 0, stockValue: 0 },
  );
  const categories = computed(() => data.value?.categories ?? []);

  const products = computed(() => {
    const all = data.value?.allProducts ?? [];
    const q = searchTerm.value.trim().toLowerCase();
    if (!q) return all;
    return all.filter(
      (p) => p.name.toLowerCase().includes(q) || (p.sku ?? "").toLowerCase().includes(q),
    );
  });

  const needsAction = computed(() => products.value.filter((p) => p.health !== "healthy"));

  return { overview, categories, products, needsAction, searchTerm, loading };
}
