import actionDelivery from "./assets/action-delivery.png";
import actionReplenishment from "./assets/action-replenishment.png";
import actionStockCount from "./assets/action-stock-count.png";
import actionTransfers from "./assets/action-transfers.png";
import stockBlueprintBg from "/bgs/warehouse-background.png";
import stockWarehouse from "./assets/stock-warehouse.png";

interface StockActionVisual {
  key: string;
  label: string;
  image: string;
}

export const stockVisualAssets = {
  blueprintBg: stockBlueprintBg,
  warehouse: stockWarehouse,
};

export const stockActionVisuals: StockActionVisual[] = [
  { key: "count", label: "Stock count", image: actionStockCount },
  { key: "transfers", label: "Transfers", image: actionTransfers },
  { key: "replenishment", label: "Replenishment", image: actionReplenishment },
  { key: "delivery", label: "Incoming delivery", image: actionDelivery },
];

export function productImageSrc(image: string | null) {
  if (!image) return null;
  if (image.startsWith("data:")) return image;
  return `data:image/jpeg;base64,${image}`;
}
