import type { StockHealth, StockMovementKind } from "./stock.types";

export const LOW_STOCK_THRESHOLD = 20;
export const FALLBACK_REORDER_POINT = 20;

export function formatCount(n: number): string {
  return Math.round(n).toLocaleString("en-US");
}

export function formatCompact(n: number): string {
  const abs = Math.abs(n);
  if (abs >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (abs >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
  return String(Math.round(n));
}

export function formatTime(iso: string | null): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" });
}

export function healthFor(onHand: number): StockHealth {
  if (onHand <= 0) return "critical";
  if (onHand < LOW_STOCK_THRESHOLD) return "low";
  return "healthy";
}

interface HealthMeta {
  label: string;
  text: string;
  bg: string;
  dot: string;
}

export function movementKind(op: string | null): StockMovementKind {
  if (!op) return "transfer";
  const o = op.toLowerCase();
  if (o.includes("out") || o.includes("dispatch") || o.includes("delivery")) return "sold";
  if (o.includes("in") || o.includes("receipt") || o.includes("return")) return "received";
  return "transfer";
}

export function signedQty(rawQty: number, kind: StockMovementKind): number {
  return kind === "sold" ? -Math.abs(rawQty) : Math.abs(rawQty);
}

export const HEALTH_META: Record<StockHealth, HealthMeta> = {
  healthy: { label: "Healthy", text: "text-green-600", bg: "bg-green-50", dot: "bg-green-500" },
  low: { label: "Low stock", text: "text-amber-600", bg: "bg-amber-50", dot: "bg-amber-500" },
  critical: { label: "Critical", text: "text-red-600", bg: "bg-red-50", dot: "bg-red-500" },
};
