<template>
  <F7Page
    class="page-stock bg-stock-bg bg-cover bg-center"
    :style="{
      backgroundImage: `linear-gradient(to bottom, transparent 25vh, var(--color-stock-bg) 30vh), linear-gradient(to right, var(--color-stock-bg) 0%, transparent 30%), url(${stockVisualAssets.blueprintBg})`,
    }"
  >
    <F7Navbar title="Stock" large transparent :sliding="true">
      <template #nav-right>
        <div class="flex items-center gap-2 pr-3">
          <F7Link href="/stock/search/" icon-only class="!w-10 !h-10">
            <span class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]">
              <ILucideSearch class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
          <F7Link icon-only class="!w-10 !h-10">
            <span class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]">
              <ILucideScanLine class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
        </div>
      </template>
    </F7Navbar>

    <div
      class="relative mx-auto min-h-full overflow-hidden px-[18px] pb-[116px]"
    >
      <section
        class="relative z-10 mb-[22px] overflow-hidden rounded-3xl border border-[rgba(219,228,244,0.82)] px-5 pt-6 pb-5 backdrop-blur-[22px] bg-[linear-gradient(145deg,rgba(255,255,255,0.88),rgba(244,248,255,0.62)),rgba(255,255,255,0.72)] shadow-[0_22px_46px_rgba(31,58,107,0.1),inset_0_1px_0_rgba(255,255,255,0.96)] max-[430px]:px-4"
      >
        <div class="relative z-20 mb-5">
          <h2 class="m-0 text-[20px] leading-none text-[#090e24]">
            Stock overview
          </h2>
          <button
            type="button"
            class="mt-3 text-[15px] leading-none text-[#0b73ff]"
          >
            All locations
          </button>
        </div>

        <div class="relative z-20">
          <img
            :src="stockVisualAssets.warehouse"
            alt=""
            loading="eager"
            class="absolute -bottom-5 right-0 z-10 h-[180px] w-[50%] object-contain object-right-bottom [mask-image:linear-gradient(to_right,transparent_0%,rgba(0,0,0,0.5)_24%,black_48%)] drop-shadow-[0_22px_28px_rgba(49,69,105,0.16)]"
          />
          <div class="relative z-20 grid w-[60%] grid-cols-2 gap-2 max-[430px]:gap-1.5">
            <StockMetricCard
              v-for="metric in metrics"
              :key="metric.label"
              :label="metric.label"
              :value="metric.value"
              :icon="metric.icon"
              :tone="metric.tone"
            />
          </div>
        </div>
      </section>

      <div
        class="relative z-10 mb-[22px] grid grid-cols-2 grid-rows-2 gap-2.5 max-[430px]:gap-2"
      >
        <StockActionTile
          v-for="action in stockActionVisuals"
          :key="action.key"
          :label="action.label"
          :image="action.image"
        />
      </div>

      <section class="relative z-10 mb-3.5">
        <div class="mb-3.5 flex items-center justify-between gap-3">
          <div class="flex min-w-0 items-center gap-2.5">
            <span
              class="flex h-8 w-8 items-center justify-center rounded-[13px] bg-[rgba(11,115,255,0.1)] text-[#0b73ff]"
            >
              <ILucidePackage class="h-[18px] w-[18px]" />
            </span>
            <h2 class="m-0 text-[20px] font-[820] leading-none text-[#090e24]">
              Products
            </h2>
          </div>
        </div>

        <div v-if="products.length" class="flex flex-col gap-2">
          <StockNeedCard
            v-for="item in products"
            :key="item.ruid"
            :name="item.name"
            :sku-label="item.sku ? `SKU ${item.sku}` : '—'"
            :state-label="productStateLabel(item.onHand)"
            :health="item.health"
            :image-src="productImageSrc(item.image)"
            @open="openProduct(item.ruid)"
          />
        </div>
        <p v-else class="mx-0.5 mt-2.5 text-sm font-[540] text-[#657096]">
          No products found.
        </p>
      </section>
    </div>

    <StockProductSheet
      v-model:opened="sheetOpen"
      :product-ruid="selectedRuid"
    />
  </F7Page>
</template>

<script setup lang="ts">
import StockActionTile from "../components/StockActionTile.vue";
import StockMetricCard from "../components/StockMetricCard.vue";
import StockNeedCard from "../components/StockNeedCard.vue";
import StockProductSheet from "../components/StockProductSheet.vue";
import { useStockDashboard } from "../composables/useStockDashboard";
import { formatCompact, formatCount } from "../stock.format";
import {
  productImageSrc,
  stockActionVisuals,
  stockVisualAssets,
} from "../stock.visuals";

const { overview, products } = useStockDashboard();

const sheetOpen = ref(false);
const selectedRuid = ref<string | null>(null);

const metrics = computed(
  () =>
    [
      {
        label: "Total SKUs",
        value: formatCount(overview.value.totalSkus),
        icon: "package",
        tone: "blue",
      },
      {
        label: "Low stock",
        value: formatCount(overview.value.lowStock),
        icon: "low",
        tone: "orange",
      },
      {
        label: "Out of stock",
        value: formatCount(overview.value.outOfStock),
        icon: "alert",
        tone: "red",
      },
      {
        label: "Stock value",
        value: `DZD ${formatCompact(overview.value.stockValue)}`,
        icon: "value",
        tone: "violet",
      },
    ] as const,
);

function productStateLabel(onHand: number) {
  if (onHand <= 0) return "Out of stock";
  return `${formatCompact(onHand)} units`;
}

function openProduct(ruid: string) {
  selectedRuid.value = ruid;
  sheetOpen.value = true;
}
</script>
