<template>
  <div class="min-w-0 rounded-[16px] border border-[rgba(222,230,244,0.82)] bg-[linear-gradient(145deg,rgba(255,255,255,0.88),rgba(245,249,255,0.66)),rgba(255,255,255,0.72)] backdrop-blur-[18px] px-2.5 pt-2.5 pb-3 shadow-[0_16px_28px_rgba(39,66,112,0.08),inset_0_1px_0_rgba(255,255,255,0.95)]">
    <div :class="['flex items-center justify-center w-6 h-6 rounded-[10px] mb-2', iconClass]">
      <ILucidePackageCheck v-if="icon === 'package'" class="h-3.5 w-3.5" />
      <ILucideArrowDown v-else-if="icon === 'low'" class="h-3.5 w-3.5" />
      <ILucideCircleAlert v-else-if="icon === 'alert'" class="h-3.5 w-3.5" />
      <ILucideDiamond v-else class="h-3.5 w-3.5" />
    </div>
    <p class="text-[11px] font-medium leading-tight text-[#536187]">{{ label }}</p>
    <p class="mt-1 whitespace-nowrap text-[clamp(12px,3.8vw,20px)] font-extrabold leading-tight text-[#090e24]">
      {{ value }}
    </p>
  </div>
</template>

<script setup lang="ts">
const props = defineProps<{
  label: string;
  value: string;
  icon: "package" | "low" | "alert" | "value";
  tone: "blue" | "orange" | "red" | "violet";
}>();

const TONE: Record<string, string> = {
  blue: "text-blue-600 bg-blue-500/10",
  orange: "text-orange-500 bg-orange-500/10",
  red: "text-red-500 bg-red-500/10",
  violet: "text-violet-500 bg-violet-500/[0.12]",
};

const iconClass = computed(() => TONE[props.tone]);
</script>
